CLOSE = re.compile(
    r'conn=(?P<conn>\S+)\s+user=(?P<user>\S+)\s+event=close\s+'
    r'code=(?P<code>\d+)\s+reason="(?P<reason>[^"]*)"\s+dur_s=(?P<dur>\d+)'
)

def bucket(code):
    if code in (1000, 1001):
        return 'clean'
    if code in (1005, 1006):
        return 'abnormal'
    if 4000 <= code <= 4999:
        return 'application'
    return 'protocol_error'

