for line in lines:
    m = CLOSE.search(line)
    if m is None:
        non_close += 1
        continue
    code = int(m.group('code'))
    b = bucket(code)
    if b not in by_bucket:
        by_bucket[b] = 0
        bucket_order.append(b)
    by_bucket[b] += 1
    if code not in by_code:
        by_code[code] = 0
        code_order.append(code)
    by_code[code] += 1
    if b == 'abnormal':
        abnormal_durs.append(int(m.group('dur')))

closes = sum(by_bucket.values())
result = {
    'closes': closes,
    'non_close_lines': non_close,
    'by_bucket': {b: by_bucket[b] for b in sorted(bucket_order)},
    'by_code': {str(c): by_code[c] for c in sorted(code_order)},
    'abnormal_pct': round(100.0 * by_bucket.get('abnormal', 0) / closes, 2),
    'max_abnormal_dur_s': max(abnormal_durs),
}

