import re
from collections import Counter

def bucket(msg):
    n = len(msg.split())
    if n <= 2:
        return "short"
    elif n <= 5:
        return "medium"
    else:
        return "long"

buckets = Counter()
for l in lines:
    m = re.search(r'type=(\w+) msg="([^"]*)"', l)
    if not m:
        continue
    mtype, msg = m.group(1), m.group(2)
    if mtype == 'system':
        continue
    buckets[bucket(msg)] += 1
result = buckets.most_common(1)[0][0]

DEVICE_STATES = {'ONLINE', 'DEGRADED', 'FAULTED', 'OFFLINE', 'UNAVAIL', 'REMOVED'}

pools = {}
in_progress = []
current = None

for raw in lines:
    line = raw.rstrip()
    if not line.strip():
        continue
    stripped = line.strip()
    if stripped.startswith('pool:'):
        current = stripped.split(':', 1)[1].strip()
        pools[current] = {
            'read': 0, 'write': 0, 'cksum': 0,
            'devices': 0, 'devices_with_errors': 0,
            'scrub_errors': None,
        }
        continue
    if current is None:
        continue
    if stripped.startswith('scan:'):
        if 'scrub in progress' in stripped:
            in_progress.append(current)
        elif ' with ' in stripped and ' errors ' in stripped:
            pools[current]['scrub_errors'] = int(
                stripped.split(' with ', 1)[1].split(' errors', 1)[0]
            )
        continue
    if not line.startswith('\t'):
        continue
    body = line[1:]
    tokens = body.split()
    # progress lines and the NAME/STATE header are not device rows
    if len(tokens) < 5 or tokens[1] not in DEVICE_STATES:
        continue
    if not all(t.isdigit() for t in tokens[2:5]):
        continue
    indent = len(body) - len(body.lstrip(' '))
    if indent < 4:
        continue  # pool row or vdev row, whose counters are aggregates
    read, write, cksum = (int(t) for t in tokens[2:5])
    entry = pools[current]
    entry['read'] += read
    entry['write'] += write
    entry['cksum'] += cksum
    entry['devices'] += 1
    if read or write or cksum:
        entry['devices_with_errors'] += 1

result = {
    "pools": {p: pools[p] for p in sorted(pools)},
    "scrub_in_progress": sorted(in_progress),
    "total_leaf_devices": sum(p['devices'] for p in pools.values()),
    "total_device_errors": sum(
        p['read'] + p['write'] + p['cksum'] for p in pools.values()
    ),
}

