POLICY_MIN = 'TLSv1.2'
ORDER = {'TLSv1.0': 0, 'TLSv1.1': 1, 'TLSv1.2': 2, 'TLSv1.3': 3}

by_version = {}
below_policy_peers = []
used_bits = []
failures = {'ssl_connect_error': 0, 'lost_connection': 0, 'tls_not_offered': 0}
non_tls_connect_errors = 0

for raw in lines:
    line = raw.rstrip()
    if not line:
        continue
    if ' with cipher ' in line:
        head, tail = line.split(' with cipher ', 1)
        version = head.rsplit(': ', 1)[1].strip()
        peer = head.split(' established to ', 1)[1].split('[', 1)[0]
        bits = tail.rsplit('(', 1)[1].split(' ', 1)[0]
        used_bits.append(int(bits.split('/')[0]))
        by_version[version] = by_version.get(version, 0) + 1
        if ORDER[version] < ORDER[POLICY_MIN]:
            below_policy_peers.append(peer)
    elif 'SSL_connect error to' in line:
        failures['ssl_connect_error'] += 1
    elif 'while performing TLS handshake' in line:
        failures['lost_connection'] += 1
    elif 'TLS is required, but was not offered' in line:
        failures['tls_not_offered'] += 1
    elif 'Connection timed out' in line:
        non_tls_connect_errors += 1

result = {
    "established_by_version": {v: by_version[v] for v in sorted(by_version)},
    "below_policy_minimum": len(below_policy_peers),
    "peers_below_policy": sorted(set(below_policy_peers)),
    "min_cipher_bits_used": min(used_bits),
    "handshake_failures": {k: failures[k] for k in sorted(failures)},
    "non_tls_connect_errors": non_tls_connect_errors,
}

