from datetime import datetime
from collections import defaultdict

MAX_SAMPLE_GAP_S = 60
TS_FORMAT = '%Y-%m-%d %H:%M:%S'

samples = defaultdict(list)
malformed = 0
for raw in lines:
    line = raw.strip()
    if not line:
        continue
    parts = [p.strip() for p in line.split(',')]
    fields = dict(p.split('=', 1) for p in parts[1:] if '=' in p)
    util = fields.get('util_pct', '')
    if not util.isdigit():
        malformed += 1
        continue
    samples[fields['gpu']].append((datetime.strptime(parts[0], TS_FORMAT), int(util)))


def band(util):
    if util >= 75:
        return 'high'
    if util >= 25:
        return 'medium'
    return 'low'


per_gpu = {}
for gpu in sorted(samples):
    ordered = sorted(samples[gpu])
    dwell = {'high': 0, 'medium': 0, 'low': 0}
    gap_s = 0
    for (t0, u0), (t1, _) in zip(ordered, ordered[1:]):
        delta = int((t1 - t0).total_seconds())
        if delta > MAX_SAMPLE_GAP_S:
            gap_s += delta
            continue
        dwell[band(u0)] += delta
    per_gpu[gpu] = {
        "samples": len(ordered),
        "dwell_s": {k: dwell[k] for k in sorted(dwell)},
        "unsampled_gap_s": gap_s,
        "covered_s": sum(dwell.values()),
    }

result = {
    "per_gpu": per_gpu,
    "malformed_samples": malformed,
    "total_high_band_s": sum(v["dwell_s"]["high"] for v in per_gpu.values()),
}

import re
from collections import Counter

HEADER = re.compile(r'E ANR\s*:\s*ANR in (\S+)(?: \((\S+)\))?$')
REASON = re.compile(r'E ANR\s*:\s*Reason: (.*)$')
DISPATCH_MS = re.compile(r'does not respond within (\d+)ms')

REPORT_THRESHOLD_MS = 5000

records = []
current = None
for raw in lines:
    line = raw.rstrip()
    if not line:
        continue
    head = HEADER.search(line)
    if head is not None:
        current = {
            'package': head.group(1),
            'component': head.group(2).split('/')[-1] if head.group(2) else None,
            'reason': None,
        }
        records.append(current)
        continue
    if current is None:
        continue
    reason = REASON.search(line)
    if reason is not None and current['reason'] is None:
        current['reason'] = reason.group(1)


def category(reason):
    if reason.startswith('Input dispatching timed out'):
        return 'input_dispatch'
    if reason.startswith('Broadcast of Intent'):
        return 'broadcast'
    if reason.startswith('executing service'):
        return 'service'
    return 'other'


clusters = Counter()
by_package = Counter()
by_component = Counter()
dispatch_timeouts = []
incomplete = 0

for rec in records:
    by_package[rec['package']] += 1
    if rec['component']:
        by_component[rec['package'] + '/' + rec['component']] += 1
    if rec['reason'] is None:
        incomplete += 1
        continue
    clusters[rec['package'] + '|' + category(rec['reason'])] += 1
    ms = DISPATCH_MS.search(rec['reason'])
    if ms is not None:
        dispatch_timeouts.append(int(ms.group(1)))

result = {
    "records": len(records),
    "incomplete_records": incomplete,
    "clusters": dict(sorted(clusters.items())),
    "by_component": dict(sorted(by_component.items())),
    "most_affected_package": sorted(
        by_package.items(), key=lambda kv: (-kv[1], kv[0])
    )[0][0],
    "dispatch_timeouts_ms": sorted(dispatch_timeouts),
    "at_or_over_threshold_ms": sum(
        1 for v in dispatch_timeouts if v >= REPORT_THRESHOLD_MS
    ),
}

from datetime import datetime

LOCK_TIMEOUT_MS = 15000.0
TS_FORMAT = '%Y-%m-%d %H:%M:%S.%f'

waits = {}
acquired = {}
timed_out = []
acquired_without_wait = []
lock_modes = {}

for raw in lines:
    line = raw.rstrip()
    if not line:
        continue
    stamp, rest = line.split(' UTC ', 1)
    when = datetime.strptime(stamp, TS_FORMAT)
    pid = rest.split(']', 1)[0].lstrip('[')
    body = rest.split(']', 1)[1].strip()
    if 'still waiting for' in body:
        mode = body.split('still waiting for ', 1)[1].split(' ', 1)[0]
        lock_modes[pid] = mode
        waits.setdefault(pid, when)
    elif ' acquired ' in body:
        mode = body.split(' acquired ', 1)[1].split(' ', 1)[0]
        lock_modes.setdefault(pid, mode)
        reported = float(body.rsplit(' after ', 1)[1].split(' ', 1)[0])
        if pid in waits:
            measured = (when - waits[pid]).total_seconds() * 1000.0
        else:
            measured = None
            acquired_without_wait.append(pid)
        acquired[pid] = (measured, reported)
    elif 'canceling statement due to lock timeout' in body:
        timed_out.append(pid)

per_pid = {}
for pid in sorted(acquired):
    measured, reported = acquired[pid]
    per_pid[pid] = {
        "lock_mode": lock_modes[pid],
        "measured_wait_ms": round(measured, 3) if measured is not None else None,
        "reported_wait_ms": reported,
        "at_or_over_lock_timeout": reported >= LOCK_TIMEOUT_MS,
    }

result = {
    "acquired": per_pid,
    "timed_out_pids": sorted(timed_out),
    "acquired_without_wait_record": sorted(acquired_without_wait),
    "at_or_over_lock_timeout_count": sum(
        1 for v in per_pid.values() if v["at_or_over_lock_timeout"]
    ),
    "max_measured_wait_ms": max(
        v["measured_wait_ms"] for v in per_pid.values() if v["measured_wait_ms"] is not None
    ),
}

def split_top_level(payload):
    """Split on commas that are not inside parentheses."""
    items, depth, buf = [], 0, ''
    for ch in payload:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        if ch == ',' and depth == 0:
            if buf.strip():
                items.append(buf.strip())
            buf = ''
        else:
            buf += ch
    if buf.strip():
        items.append(buf.strip())
    return items


def clock_seconds(hms):
    h, m, s = hms.split(':')
