    image, layer, status, size = m.groups()
    entry = images.setdefault(image, {'layers': {}, 'bytes': 0})
    layer_owners[layer].add(image)
    if status == 'Already exists':
        entry['layers'][layer] = 'cached'
    else:
        entry['layers'].setdefault(layer, 'downloaded')
    if not size.isdigit():
        # progress line emitted before the manifest size was known
        unknown_size_lines += 1
    elif status == 'Download complete':
        entry['bytes'] += int(size)

