    entry = images[image]
    total = len(entry['layers'])
    cached = sum(1 for v in entry['layers'].values() if v == 'cached')
    per_image[image] = {
        "layers": total,
        "cached": cached,
        "downloaded": total - cached,
        "bytes_downloaded": entry['bytes'],
        "cache_hit_ratio": round(cached / total, 4),
    }

result = {
    "per_image": per_image,
    "unknown_size_lines": unknown_size_lines,
