# Access-point state machine: a station is only "joined" if it authenticated
# and then associated on the same radio, and it is still joined at the end of
# the log unless a later disassociated/deauthenticated line clears it.
import re

pattern = re.compile(
    r"^(?P<radio>wlan\d+): STA (?P<mac>[0-9a-f:]{17}) IEEE 802\.11: "
    r"(?P<event>authenticated|associated|disassociated|deauthenticated)\b"
)
authed = set()
joined = []
dropped = []
orphan_assoc = []
for line in lines:
    m = pattern.match(line)
    if not m:
        continue
    key = (m.group("radio"), m.group("mac"))
    event = m.group("event")
    if event == "authenticated":
        authed.add(key)
    elif event == "associated":
        if key in authed:
            if key not in joined:
                joined.append(key)
        else:
            orphan_assoc.append(m.group("mac"))
    else:
        if key in joined:
            joined.remove(key)
        dropped.append(m.group("mac"))

result = {
    "still_joined": sorted(mac for _, mac in joined),
    "dropped": sorted(set(dropped)),
    "associated_without_auth": sorted(set(orphan_assoc)),
    "radios_seen": sorted({radio for radio, _ in authed}),
}

# Elevator controller trace: pair door_open with the next door_close per car.
# Intermediate events (door_hold, door_obstruct) must not break a pair, and an
# open that is never closed before the end of the log counts as dangling.
open_car = {}
stats = {}
for line in lines:
    if not line.strip():
        continue
    fields = {}
    for token in line.split(" ")[1:]:
        key, _, value = token.partition("=")
        fields[key] = value
    car = fields["car"]
    if car not in stats:
        stats[car] = {"completed": 0, "dangling": 0}
    event = fields["event"]
    if event == "door_open":
        if open_car.get(car) is not None:
            stats[car]["dangling"] += 1
        open_car[car] = fields["floor"]
    elif event == "door_close":
        if open_car.get(car) is not None:
            stats[car]["completed"] += 1
            open_car[car] = None
for car, still_open in open_car.items():
    if still_open is not None:
        stats[car]["dangling"] += 1
result = stats

# vsftpd xferlog. Only OK transfers contribute bytes; FAIL rows are counted
# separately per user so a user with zero successful bytes still appears.
import re

row = re.compile(
    r'^\w{3} \w{3} +\d+ \d{2}:\d{2}:\d{2} \d{4} \[pid \d+\] \[(?P<user>[^\]]+)\] '
    r'(?P<status>OK|FAIL) (?P<op>UPLOAD|DOWNLOAD): Client "(?P<ip>[^"]+)", '
    r'"(?P<path>[^"]+)", (?P<bytes>\d+) bytes, (?P<rate>\d+\.\d{2})Kbyte/sec$'
)
users = {}
for line in lines:
    m = row.match(line)
    if not m:
        continue
    user = users.setdefault(m.group("user"), {
        "ok": 0, "failed": 0, "up_bytes": 0, "down_bytes": 0, "peak_kbps": 0.0})
    if m.group("status") == "FAIL":
        user["failed"] += 1
        continue
    user["ok"] += 1
    size = int(m.group("bytes"))
    if m.group("op") == "UPLOAD":
        user["up_bytes"] += size
    else:
        user["down_bytes"] += size
    user["peak_kbps"] = max(user["peak_kbps"], float(m.group("rate")))

result = {
    "per_user": {u: users[u] for u in sorted(users)},
    "total_ok": sum(u["ok"] for u in users.values()),
    "total_failed": sum(u["failed"] for u in users.values()),
}

# Thread-pool snapshot. Rejection ratio is rejected/(rejected+completed) per
# node, and a pool is saturated when its queue is at or above 180.
totals = {}
saturated = []
for line in lines:
    if not line.strip():
        continue
    f = {}
    for token in line.split():
        key, _, value = token.partition("=")
        f[key] = value
    node = f["node"]
    rejected = int(f["rejected"])
    completed = int(f["completed"])
    bucket = totals.setdefault(node, {"rejected": 0, "completed": 0, "pools": 0})
    bucket["rejected"] += rejected
    bucket["completed"] += completed
    bucket["pools"] += 1
    if int(f["queue"]) >= 180:
        saturated.append(node + "/" + f["pool"])

per_node = {}
for node in sorted(totals):
    bucket = totals[node]
    handled = bucket["rejected"] + bucket["completed"]
    per_node[node] = {
        "pools": bucket["pools"],
        "rejected": bucket["rejected"],
        "completed": bucket["completed"],
        "reject_ppm": round(bucket["rejected"] / handled * 1000000, 2),
    }
result = {"per_node": per_node, "saturated_pools": sorted(saturated)}

