# Fleet telematics. Pair each ignition-on with the next ignition-off for the
# same vehicle; an unmatched "off" is ignored and a trailing "on" is open.
from datetime import datetime

FMT = "%Y-%m-%dT%H:%M:%SZ"
pending = {}
trips = {}
open_trips = []
stray_off = []
for line in lines:
    if not line.strip():
        continue
    stamp_text, rest = line.split(" ", 1)
    fields = dict(tok.split("=", 1) for tok in rest.split())
    stamp = datetime.strptime(stamp_text, FMT)
    veh = fields["veh"]
    odo = int(fields["odo_km"])
    if fields["ignition"] == "on":
        pending[veh] = (stamp, odo)
    else:
        start = pending.pop(veh, None)
        if start is None:
            stray_off.append(veh)
            continue
        seconds = (stamp - start[0]).total_seconds()
        bucket = trips.setdefault(veh, {"trips": 0, "minutes": 0.0, "km": 0})
        bucket["trips"] += 1
        bucket["minutes"] += seconds / 60.0
        bucket["km"] += odo - start[1]

for veh in sorted(pending):
    open_trips.append(veh)

report = {}
for veh in sorted(trips):
    bucket = trips[veh]
    minutes = round(bucket["minutes"], 2)
    report[veh] = {
        "trips": bucket["trips"],
        "driving_minutes": minutes,
        "distance_km": bucket["km"],
        "avg_kmh": round(bucket["km"] / (minutes / 60.0), 2),
    }
result = {"per_vehicle": report, "open_at_end": open_trips,
          "unmatched_off": sorted(stray_off)}

